import { test } from "node:test";
import assert from "node:assert/strict";
import { clamp } from "./clamp.mjs";

test("value below range returns low", () => {
  assert.equal(clamp(2, 5, 10), 5);
});

test("value at low boundary returns value", () => {
  assert.equal(clamp(5, 5, 10), 5);
});

test("value inside range returns value", () => {
  assert.equal(clamp(7, 0, 10), 7);
});

test("value at high boundary returns value", () => {
  assert.equal(clamp(10, 0, 10), 10);
});

test("value above range returns high", () => {
  assert.equal(clamp(15, 0, 10), 10);
});
